INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (101401102, 101401107, "トゥルーエンドケース", 0, 0, 0, 101401106, 0, 0, 0, 1015, 101401105, 0, 0, 0, 0, 0, 0, 101401105, 101401108, 101401110, 0, 0, 0, 0, 0, 101401105, 101401109, 101401104, 0, "前から３番目の敵を中心とした範囲内の敵の魔法防御力を特大ダウン、ＴＰ上昇を小ダウンさせるフィールドを展開し、行動速度を中ダウンさせ、【カウントダウン】を付与し、５カウント後に敵全体に魔法小ダメージを与える。このスキルによるダメージでは敵のＴＰは回復しない。【証拠】が最大の場合、このスキルは必ずクリティカルする。", 0, 0, 0, 0, 101401105, 0, 101401105, 1, 101401103, 101401111, 0, 101401101, 1014011, 101401104, 0, 0, 101401105);
