INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (102802202, 102802207, "ファイアスラッシュ++", 0, 102802202, 0, 102802206, 0, 102802205, 0, 2001, 0, 0, 0, 1.45, 0, 0, 0, 0, 102802208, 102802210, 0, 0, 0, 0, 0, 102802205, 102802209, 0, 0, "前方範囲内の敵に物理大ダメージを与え、物理防御力を小ダウンさせる。自分のＨＰ割合が低いほど、ダメージ倍率が最大２倍まで増加する。アキノ（同名キャラを除く）が味方にいる場合、自分のＨＰ回復量が特大ダウン、物理・魔法防御力が大ダウンするが、自分に【競争心】を付与し、前方の火属性の味方の物理攻撃力を特大アップさせる。【競争心】付与時にＨＰが０になるダメージを受けると、ＨＰ１で耐える。", 0, 0, 0, 0, 102802205, 0, 102802205, 1, 102802203, 0, 0, 102802201, 1028022, 102802204, 0, 0, 0);
