INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (103001102, 103001107, "忍法・烈火之紅蓮旋風", 0, 0, 0, 103001106, 0, 0, 0, 1001, 0, 0, 0, 0, 0, 0, 0, 0, 103001108, 0, 0, 0, 0, 0, 0, 103001105, 0, 0, 0, "前方範囲内の敵に物理特大ダメージを与え、自分の物理攻撃力を短時間大アップする。敵を倒した場合、自分に【火遁の印】（上限５）を１個付与する。倒した敵の数に応じて【火遁の印】の付与数と、物理攻撃力のアップ量が増加する。【火遁の印】付与中、【火遁の印】を１個消費し、自分のＴＰを特大回復する。", 0, 0, 0, 0, 0, 0, 103001107, 1, 103001103, 0, 0, 103001101, 1030011, 103001104, 0, 0, 0);
