INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (104000302, 104000307, "パラライズアロー", 104000313, 104000302, 104000312, 104000306, 0, 104000308, 104000304, 2007, 104000305, 0, 0, 1.06, 0, 0, 0, 104000305, 104000308, 104000310, 104000314, 104000312, 0, 0, 0, 104000305, 104000309, 104000304, 0, "前方範囲内の敵に物理小ダメージを与え、麻痺状態にする。発動時既に対象が毒状態だった場合、ダメージと麻痺状態の効果時間が増加する。発動時既に対象が毒状態かつ猛毒状態だった場合、物理防御力を小ダウンさせる。自分を中心とした範囲内の味方の数が２キャラ以下の場合、ダメージが増加する。", 0, 0, 0, 0, 0, 0, 104000307, 1, 104000303, 104000311, 0, 104000301, 1040003, 104000304, 104000315, 104000314, 0);
