INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (106900302, 106900307, "八尺瓊勾玉・減葬", 106900313, 0, 0, 106900306, 0, 0, 0, 2004, 0, 0, 0, 1.7, 0, 0, 0, 0, 106900308, 106900310, 0, 106900312, 0, 0, 0, 106900305, 106900309, 0, 0, "前方の敵の受ける物理・魔法ダメージを中アップさせ、物理・魔法防御力と物理・魔法クリティカルダメージを小ダウンさせる。自分を一定時間物理・魔法回避状態にする。敵の数に応じて、物理・魔法回避状態の効果時間が減少する。初回発動時、さらに味方全体を覇瞳神眼状態にする。覇瞳神眼状態は受けるダメージを１回無効化し、その後解除される。", 0, 0, 0, 0, 0, 0, 0, 1, 106900303, 106900311, 0, 106900301, 1069003, 106900304, 0, 0, 0);
