INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (123301102, 123301107, "スライミィダーリン♡", 0, 0, 0, 123301106, 0, 0, 0, 1017, 0, 0, 0, 0, 0, 0, 0, 0, 123301108, 123301110, 0, 0, 0, 0, 0, 123301105, 123301109, 0, 0, "【召喚・挑発】敵全体に物理大ダメージを与え、物理防御力を小ダウンさせる。自分を短時間無敵状態にし、敵全体を挑発する。アカ、アオが味方にいる場合１体につき追加で敵全体に物理小ダメージを与え、そうでない場合召喚する。アカのスキルは目の前の敵１キャラを中心とした範囲内の敵に物理中ダメージを与え、スタンさせ、物理攻撃力を中ダウン、物理防御力を小ダウンさせる。アオのスキルは味方全体のＨＰとＴＰを小回復、物理攻撃力を特大アップ、物理クリティカルを大アップ、物理クリティカルダメージを小アップさせる。", 0, 0, 0, 0, 0, 0, 0, 0, 123301103, 0, 0, 123301101, 1233011, 123301104, 0, 0, 0);
INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (123301202, 0, "カムカムスライム+", 0, 123301202, 0, 0, 0, 0, 123301201, 2001, 0, 0, 0, 0.59, 0, 0, 0, 0, 0, 0, 0, 0, 123301203, 0, 0, 123301205, 0, 123301204, 0, "ＴＰが最大値に達しているキャラを除く最もＴＰが多い敵を中心とした範囲内の敵に物理大ダメージを与え、ＴＰを中ダウン、行動速度を大ダウンさせる。このスキルによるダメージでは敵のＴＰは回復しない。", 0, 0, 0, 0, 0, 0, 0, 0, 123301203, 0, 0, 123301201, 1233012, 123301204, 0, 0, 0);
