INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (126400102, 126400107, "ギガンティックアームパンチ", 0, 0, 0, 126400106, 0, 0, 0, 1001, 0, 0, 0, 0, 0, 0, 0, 126400105, 0, 0, 0, 0, 0, 0, 0, 126400105, 0, 126400103, 0, "前方範囲内の敵に物理大ダメージを与え、【フルチャージ】状態になり【バッテリー】（上限７）を７個充填し、１ヒットは必ずクリティカルする。【バッテリー】が１個以上の場合、このスキルのクリティカルダメージは３倍になる。そうでない場合、自分の物理攻撃力と加算行動速度を特大アップさせる。", 0, 0, 0, 0, 0, 0, 0, 0, 126400103, 0, 0, 126400101, 1264001, 126400104, 0, 0, 0);
