INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (126401202, 126401207, "ジャンピングロケットパンチ+", 0, 0, 0, 126401206, 0, 126401207, 126401201, 2001, 0, 0, 0, 1.18, 0, 0, 0, 0, 126401208, 126401210, 0, 0, 0, 0, 0, 126401205, 126401209, 0, 0, "最も後ろの敵に物理大ダメージを与え、受けるクリティカルダメージを小アップさせる。初回発動時、その敵の物理防御力を小ダウンさせ、自分の物理攻撃力と物理クリティカルを特大アップ、【スーパーギガンティックアーム】を付与し、ＴＰを特大回復する。【スーパーギガンティックアーム】付与中かつ【フルチャージ】状態中のスキル（オーバーヒートを除く）のクリティカルダメージは【バッテリー】の数に応じて最大４倍まで上昇する。【スーパーギガンティックアーム】は【システムダウン】状態になると失われる。", 0, 0, 0, 0, 126401207, 0, 126401207, 0, 126401203, 0, 0, 126401201, 1264012, 126401204, 0, 0, 0);
