INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (129900302, 129900307, "ヘヴィコマンド", 0, 0, 0, 129900306, 0, 0, 0, 2003, 0, 0, 0, 0.66, 0, 0, 0, 0, 129900308, 0, 0, 0, 0, 0, 0, 129900305, 0, 0, 0, "味方全体の物理攻撃力と物理クリティカルを大アップ、物理・魔法防御力を小アップさせる。自分のＴＰを大回復し、自分以外の味方のＴＰを小回復させる。味方の数に応じて、物理攻撃力と物理クリティカルのアップ量が最大７キャラ分まで増加する。", 0, 0, 0, 0, 0, 0, 0, 0, 129900303, 0, 0, 129900301, 1299003, 129900304, 0, 0, 0);
