INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (132300102, 132300107, "究極錬成‐氷炎融合‐", 0, 132300102, 0, 132300106, 0, 132300108, 0, 1003, 0, 0, 0, 0, 0, 0, 0, 0, 132300108, 132300110, 0, 0, 132300103, 0, 0, 132300105, 132300109, 0, 0, "目の前の敵１キャラに対象の物理防御力が魔法防御力より低い場合、物理ダメージ扱いになる魔法特大ダメージを与え、味方全体の魔法攻撃力を特大アップ、魔法クリティカルを大アップ、魔法クリティカルダメージを小アップさせる。発動するたびに、最大２回までダメージが増加し、３回目以降はステータスアップの効果時間が増加する。", 0, 0, 0, 0, 132300108, 0, 0, 0, 132300103, 0, 0, 132300101, 1323001, 132300104, 0, 0, 0);
