INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (132500202, 132500207, "アダルトメランコリー", 0, 0, 0, 132500206, 0, 0, 0, 2004, 132500205, 0, 0, 1.05, 0, 0, 0, 132500205, 0, 0, 0, 0, 0, 0, 0, 132500205, 0, 0, 0, "敵全体の魔法防御力を中ダウン、ＴＰ上昇を小ダウン、ＴＰを大ダウンさせる。最も魔法防御力が低い敵の【虚脱】が最大の場合、さらに味方全体の魔法攻撃力を特大アップ、ＴＰ上昇を小アップ、ＴＰを中回復させる。", 0, 0, 0, 0, 0, 0, 0, 0, 132500203, 0, 0, 132500201, 1325002, 132500204, 0, 0, 0);
