INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (133100302, 0, "イモータル・ステップ", 0, 133100302, 0, 0, 0, 0, 0, 2017, 0, 0, 0, 1.05, 0, 0, 0, 0, 0, 0, 0, 0, 133100302, 0, 0, 0, 0, 0, 0, "自分に【穢レ】を付与し、物理・魔法防御力を小アップする。【穢レ】付与中は受ける特定のダメージの30％を継続ダメージに変換する。【忌火】中でない場合、このスキルの効果は発動しない。【穢レ】によって変換される継続ダメージでは味方のＴＰは回復しない。", 0, 0, 0, 0, 0, 0, 0, 0, 133100303, 0, 0, 133100301, 1331003, 133100304, 0, 0, 0);
