INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (135800102, 135800107, "涅槃雪・勧進帳", 0, 0, 0, 135800106, 0, 0, 135800101, 1004, 135800106, 0, 0, 0, 0, 0, 0, 0, 135800108, 135800110, 0, 0, 0, 0, 0, 135800105, 135800109, 0, 0, "前方の敵に魔法大ダメージを与え、魔法防御力を小ダウンさせる。最も魔法防御力が低い敵が次の状態の場合、さらに効果が発動する。【魔法防御力ダウン状態】その敵の受けるクリティカルダメージを小アップさせる。【ＴＰ上昇ダウン状態】その敵に魔法特大ダメージを与え、受ける魔法ダメージを小アップさせる。このＵＢは発動するたびに、最大３回までダメージが増加する。", 0, 0, 0, 0, 0, 0, 0, 0, 135800103, 0, 0, 135800101, 1358001, 135800104, 0, 0, 0);
INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (135800202, 135800207, "すくたれ・霜枯", 0, 0, 0, 135800206, 0, 0, 135800201, 2004, 135800206, 0, 0, 1.05, 0, 0, 0, 0, 135800208, 0, 0, 0, 0, 0, 0, 135800205, 135800209, 0, 0, "前方の敵に魔法中ダメージを与え、魔法防御力を小ダウンさせる。発動時既に最も魔法防御力が低い敵が次の状態だった場合、さらに効果が発動する。【魔法防御力ダウン状態】その敵の魔法攻撃力を大ダウンさせる。【魔法攻撃力ダウン状態】その敵に魔法大ダメージを与え、ＴＰ上昇を小ダウンさせ、味方全体のＨＰを小回復させる。", 0, 0, 0, 0, 0, 0, 0, 0, 135800203, 0, 0, 135800201, 1358002, 135800204, 0, 0, 0);
INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (135800302, 135800307, "早雪・河東節", 0, 0, 0, 135800306, 0, 0, 0, 2003, 0, 0, 0, 1.05, 0, 0, 0, 0, 135800308, 0, 0, 0, 0, 0, 0, 135800305, 0, 0, 0, "味方全体の魔法攻撃力を特大アップ、魔法クリティカルを大アップ、魔法クリティカルダメージを小アップさせ、敵全体の行動速度を大ダウン、移動速度を小ダウンさせる。最も魔法防御力が低い敵がＴＰ上昇ダウン状態だった場合、さらに敵全体に魔法大ダメージを与え、ＴＰを中ダウンさせる。", 0, 0, 0, 0, 0, 0, 135800307, 0, 135800303, 0, 0, 135800301, 1358003, 135800304, 0, 0, 0);
INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (135801202, 135801207, "すくたれ・霜枯+", 0, 0, 0, 135801206, 0, 0, 135801201, 2004, 135801206, 0, 0, 1.05, 0, 0, 0, 0, 135801208, 135801210, 0, 0, 0, 0, 0, 135801205, 135801209, 0, 0, "前方の敵に魔法大ダメージを与え、魔法防御力を小ダウンさせる。発動時既に最も魔法防御力が低い敵が次の状態だった場合、さらに効果が発動する。【魔法防御力ダウン状態】その敵の魔法攻撃力を特大ダウンさせる。【魔法攻撃力ダウン状態】追加でその敵に魔法大ダメージを与え、ＴＰ上昇を小ダウンさせ、味方全体のＨＰを小回復させる。【ＴＰ上昇ダウン状態】その敵の受けるクリティカルダメージを小アップさせる。", 0, 0, 0, 0, 0, 0, 0, 0, 135801203, 135801211, 0, 135801201, 1358012, 135801204, 0, 0, 0);
