INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (136300202, 136300207, "ゆきだる★ぺんぽこりん", 0, 0, 0, 136300206, 0, 0, 0, 2002, 0, 0, 0, 1.05, 0, 0, 0, 0, 136300208, 136300210, 0, 0, 0, 0, 0, 136300205, 136300209, 0, 0, "自分を中心とした範囲内の味方のＨＰを小回復、魔法攻撃力を特大アップさせ、前方の敵に魔法大ダメージを与える。【イルミネーションバレット】（上限10）を３個付与する。クリティカルした場合、【イルミネーションバレット】の付与数が６個になる。ＵＢで【イルミネーションバレット】を40個以上消費している場合、さらに追加で自分を中心とした範囲内の味方の魔法攻撃力を特大アップさせ、前方の敵に魔法大ダメージを与える。", 0, 0, 0, 0, 0, 0, 0, 0, 136300203, 0, 0, 136300201, 1363002, 136300204, 0, 0, 0);
