INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (136400102, 136400107, "ルミナリィギフト", 0, 0, 0, 136400106, 0, 136400107, 136400101, 1002, 0, 0, 0, 0, 0, 0, 0, 0, 136400108, 0, 0, 0, 0, 0, 0, 136400105, 136400109, 0, 0, "目の前の敵１キャラに魔法特大ダメージを与え、魔法防御力を中ダウンさせる。味方全体のＨＰを中回復し、物理無効バリアを展開する。【聖夜の愛慕】の数に応じて、バリアの無効ダメージ量が増加する。【聖夜の愛慕】が最大の場合、さらに味方全体に物理・魔法ダメージカット効果を付与し、魔法クリティカルダメージを小アップさせる。", 0, 0, 0, 0, 0, 0, 136400107, 0, 136400103, 0, 0, 136400101, 1364001, 136400104, 0, 0, 0);
INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (136400202, 136400207, "ハートフルスター", 0, 0, 0, 136400206, 0, 0, 0, 2012, 0, 0, 0, 1.05, 0, 0, 0, 0, 136400208, 0, 0, 0, 0, 0, 0, 136400205, 0, 0, 0, "【挑発】味方全体に継続ＨＰ回復状態を付与、物理・魔法防御力を中アップし、自分が敵全体を挑発する。【聖夜の愛慕】の数に応じて、物理・魔法防御力のアップ量が増加する。【聖夜の愛慕】が最大の場合、さらに味方全体に継続ＴＰ回復状態を付与する。", 0, 0, 0, 0, 0, 0, 0, 0, 136400203, 0, 0, 136400201, 1364002, 136400204, 0, 0, 0);
INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (136400302, 136400307, "ホワイトプロミス", 0, 0, 0, 136400306, 0, 0, 0, 2004, 0, 0, 0, 1.05, 0, 0, 0, 0, 136400308, 136400310, 0, 0, 0, 0, 0, 136400305, 136400309, 0, 0, "目の前の敵１キャラの魔法防御力を小ダウン、物理攻撃力を大ダウンさせ、味方全体の魔法攻撃力を大アップ、物理・魔法防御力を小アップさせる。【聖夜の愛慕】の数に応じて、魔法攻撃力と物理・魔法防御力のアップ量が増加する。【聖夜の愛慕】が最大の場合、さらに味方全体に魔法無効バリアを展開する。", 0, 0, 0, 0, 0, 0, 0, 0, 136400303, 0, 0, 136400301, 1364003, 136400304, 0, 0, 0);
INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (136410102, 136410107, "ハートフルスター", 0, 0, 0, 136410106, 0, 0, 0, 2012, 0, 0, 0, 1.05, 0, 0, 0, 0, 136410108, 0, 0, 0, 0, 0, 0, 136410105, 136410109, 0, 0, "【挑発】味方全体に継続ＨＰ回復状態を付与、物理・魔法防御力を中アップさせ、自分が敵全体を挑発する。自分がステータスアップ効果を受けるたびに【聖夜の愛慕】（上限40）が１個付与される状態になる。", 0, 0, 0, 0, 0, 0, 0, 0, 136410103, 0, 0, 136410101, 1364101, 136410104, 0, 0, 0);
