INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (136500102, 136500107, "新春・姉文字斬り", 0, 0, 0, 136500106, 0, 0, 0, 1001, 0, 0, 0, 0, 0, 0, 0, 0, 136500108, 0, 0, 0, 136500103, 0, 0, 136500105, 136500109, 136500103, 0, "目の前の敵１キャラに対象の魔法防御力が物理防御力より低い場合、魔法ダメージ扱いになる物理特大ダメージを与え、物理・魔法防御力を小ダウンさせる。味方全体の物理・魔法攻撃力を特大アップ、ＨＰを小回復させる。", 0, 0, 0, 0, 0, 0, 0, 0, 136500103, 0, 0, 136500101, 1365001, 136500104, 0, 0, 0);
INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (136500202, 136500207, "新春お姉ちゃん頭突き", 0, 0, 0, 136500206, 0, 0, 0, 2001, 136500203, 0, 0, 1.05, 0, 0, 0, 136500203, 136500208, 136500210, 0, 0, 136500203, 0, 0, 136500205, 136500209, 136500203, 0, "目の前の敵１キャラに対象の魔法防御力が物理防御力より低い場合、魔法ダメージ扱いになる物理大ダメージを与え、物理・魔法防御力を小ダウン、物理・魔法攻撃力を大ダウンさせる。自分が物理・魔法攻撃力アップ状態の場合、さらに目の前の敵１キャラの受けるクリティカルダメージを小アップさせる。", 0, 0, 0, 0, 0, 0, 0, 0, 136500203, 0, 0, 136500201, 1365002, 136500204, 0, 0, 0);
INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (136500302, 136500307, "見せつけるきょうだい愛", 0, 0, 0, 136500306, 0, 0, 0, 2012, 0, 0, 0, 1.05, 0, 0, 0, 0, 136500308, 0, 0, 0, 0, 0, 0, 136500305, 136500309, 0, 0, "【挑発】敵全体を挑発し、自分が敵から受ける行動不能を３回まで無効にする。自分が物理攻撃力アップ状態の場合、さらに味方全体の物理攻撃力を特大アップさせる。自分が魔法攻撃力アップ状態の場合、さらに味方全体の魔法攻撃力を特大アップさせる。自分が物理・魔法攻撃力アップ状態の場合、さらに味方全体のＴＰを中回復させる。", 0, 0, 0, 0, 0, 0, 0, 0, 136500303, 0, 0, 136500301, 1365003, 136500304, 0, 0, 0);
