INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (136900102, 136900107, "しゅーぱーうねうねらっしゅ", 0, 136900101, 0, 136900106, 0, 0, 136900101, 1004, 136900101, 0, 0, 0, 0, 0, 0, 136900101, 136900108, 136900110, 0, 0, 136900101, 0, 0, 136900105, 136900109, 136900101, 0, "目の前の敵１キャラに物理特大ダメージを与え、物理・魔法攻撃力と物理クリティカルを大ダウン、物理防御力を中ダウン、物理クリティカルダメージを小ダウン、受けるクリティカルダメージを小アップさせる。味方全体のＨＰを小回復させ、物理無効バリアを展開するが、物理攻撃力を小ダウンさせる。味方への物理攻撃力ダウン効果は他のスキルの効果で解除できない。", 0, 0, 0, 0, 0, 0, 0, 0, 136900103, 0, 0, 136900101, 1369001, 136900104, 0, 0, 0);
INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (136900202, 136900207, "おしょうじおしょうじ～", 136900213, 0, 136900212, 136900206, 0, 136900208, 0, 2003, 136900206, 0, 0, 1.05, 0, 0, 0, 136900205, 136900208, 136900210, 0, 136900212, 0, 0, 0, 136900205, 136900209, 0, 0, "自分を中心とした範囲内の水属性の味方の物理攻撃力を特大アップさせ、継続ＨＰ回復状態を付与し、自分を除く対象の味方のＴＰを小回復させる。自分のＴＰを小回復する。物理攻撃力ダウン状態の味方に対してはこのスキルの効果がもう一度発動する。", 0, 0, 0, 0, 0, 0, 0, 0, 136900203, 136900211, 0, 136900201, 1369002, 136900204, 0, 0, 136900210);
