INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (137600102, 137600107, "幼君の創槍", 0, 0, 0, 137600106, 0, 0, 137600101, 1002, 0, 0, 0, 0, 0, 0, 0, 137600105, 137600108, 0, 0, 0, 0, 0, 0, 137600105, 137600109, 0, 0, "目の前の敵１キャラに魔法極大ダメージを与え、魔法防御力を小ダウンさせ、味方全体の魔法クリティカルダメージを小アップさせる。初回発動時、さらに味方全体のバフ強化とダメージブーストを小アップさせる。４回目発動時、さらに自分を【進化超越】状態にする。", 0, 0, 0, 0, 0, 0, 0, 0, 137600103, 0, 0, 137600101, 1376001, 137600104, 0, 0, 0);
INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (137600202, 137600207, "エーテライザー", 0, 0, 0, 137600206, 0, 0, 0, 2002, 0, 0, 0, 0.59, 0, 0, 0, 0, 137600208, 137600210, 0, 0, 0, 0, 0, 137600205, 137600209, 0, 0, "目の前の敵１キャラに魔法大ダメージを２回与え、味方全体の魔法攻撃力と魔法クリティカルを大アップする。【進化超越】状態の場合、ダメージは魔法防御力を一定値無視し、魔法攻撃力と魔法クリティカルのアップ量が２倍になる。", 0, 0, 0, 0, 0, 0, 0, 0, 137600203, 0, 0, 137600201, 1376002, 137600204, 0, 0, 0);
INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (137600302, 137600307, "エクスブルーム", 0, 0, 0, 137600306, 0, 0, 0, 2003, 0, 0, 0, 0.59, 0, 0, 0, 0, 137600308, 137600310, 0, 0, 0, 0, 0, 137600305, 137600309, 0, 0, "味方全体のＨＰ25％を消費するが、味方全体の魔法攻撃力を特大アップ、与える魔法ダメージを小アップさせ、自分のＴＰを中回復する。味方全体のＨＰが高いほど、魔法攻撃力と与える魔法ダメージのアップ量が最大２倍まで増加する。【進化超越】状態の場合、魔法攻撃力と与える魔法ダメージのアップ量は最大２倍ではなく４倍まで増加する。このスキルによる味方へのダメージでは味方のＴＰは回復しない。", 0, 0, 0, 0, 0, 0, 0, 0, 137600303, 0, 0, 137600301, 1376003, 137600304, 0, 0, 0);
