INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (138000102, 138000107, "かんながら・ゐさなをろし", 0, 0, 0, 138000106, 0, 0, 0, 1001, 0, 0, 0, 0, 0, 0, 0, 0, 138000108, 138000110, 0, 0, 0, 0, 0, 138000105, 138000109, 0, 0, "敵全体の物理防御力を大ダウンさせ、その敵の最大ＨＰに応じて最大200万の物理割合ダメージを与え、味方全体のＨＰを大回復させる。【冥海の加護】が30個以上の場合、さらに味方全体の物理攻撃力を特大アップさせる。【冥海の加護】が最大の場合、【冥海の加護】を30個消費し、さらに味方全体の与える物理ダメージを小アップし、物理・魔法攻撃力ダウン効果と物理・魔法防御力ダウン効果を解除する。", 0, 0, 0, 0, 138000109, 0, 0, 0, 138000103, 0, 0, 138000101, 1380001, 138000104, 0, 0, 0);
