INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (138800302, 138800307, "チャーミングチャレンジ", 0, 0, 0, 138800306, 0, 0, 0, 2017, 0, 0, 0, 1.05, 0, 0, 0, 0, 138800308, 138800310, 0, 0, 0, 0, 0, 138800305, 138800309, 0, 0, "自分の物理攻撃力を大アップ、物理クリティカルを特大アップし、ＴＰを大回復する。敵の【魅惑の矢】が最大の場合、その敵の【魅惑の矢】をすべて消費し、さらにその敵の最大ＨＰに応じて最大200万の物理割合ダメージを与える。初回発動時、敵がステータスダウンを受けるたびに、その敵に【魅惑の矢】（上限20）が１個付与される状態にする。", 0, 0, 0, 0, 138800309, 0, 138800307, 0, 138800303, 138800311, 0, 138800301, 1388003, 138800304, 0, 0, 138800310);
