INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (139300202, 139300207, "シュプレンググラナーテ", 0, 139300201, 0, 139300206, 0, 0, 139300201, 2001, 139300204, 0, 0, 1.05, 0, 0, 0, 139300205, 139300208, 139300210, 0, 0, 0, 0, 0, 139300205, 139300209, 139300204, 0, "前方範囲内の敵に物理中ダメージを２回与え、物理防御力を小ダウンさせる。対象が火傷状態の場合、ダメージが増加し、さらに追加でその敵の最大ＨＰに応じて最大100万の物理割合ダメージを与える。", 0, 0, 0, 0, 139300209, 0, 139300207, 0, 139300203, 0, 0, 139300201, 1393002, 139300204, 0, 0, 0);
