INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (140100102, 140100107, "どちゃラヴ♡サマーダイヴ", 140100113, 140100102, 140100112, 140100106, 140100117, 140100108, 140100101, 1023, 0, 0, 0, 0, 140100117, 140100119, 140100117, 0, 140100108, 140100110, 0, 140100112, 140100102, 140100118, 140100116, 140100105, 140100109, 0, 0, "目の前の敵１キャラを中心とした範囲内の敵に物理大ダメージを与え、物理防御力を小ダウンさせ、火傷状態にする。目の前の敵１キャラが毒状態の場合、物理ダメージが増加し、さらに追加で最も物理防御力が低い敵に物理大ダメージを与え、受けるクリティカルダメージを小アップさせる。発動時既に目の前の敵１キャラが毒状態かつ火傷状態だった場合、さらに自分と最も前の味方の物理攻撃力と物理クリティカルを大アップ、物理クリティカルダメージを小アップさせる。", 140100112, 0, 0, 0, 0, 0, 0, 0, 140100103, 140100111, 0, 140100101, 1401001, 140100104, 140100115, 140100114, 0);
INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (140100202, 140100207, "ぎゅいーん♡フロート", 140100213, 140100202, 0, 140100206, 0, 0, 140100201, 2001, 0, 0, 0, 0.59, 0, 0, 0, 0, 140100208, 140100210, 140100214, 140100212, 0, 0, 0, 140100205, 140100209, 0, 0, "目の前の敵１キャラを中心とした範囲内の敵に物理中ダメージを与え、物理防御力を小ダウンさせる。目の前の敵１キャラが毒状態の場合、ダメージが増加し、さらに追加で最も物理防御力が低い敵に物理中ダメージを与える。目の前の敵１キャラが毒状態かつ火傷状態の場合、さらに自分と前方の自分以外で最も前の味方が敵から受ける行動不能を１回無効化し、自分と最も前の味方のＴＰを小回復させる。", 0, 0, 0, 0, 0, 0, 0, 0, 140100203, 140100211, 0, 140100201, 1401002, 140100204, 140100215, 140100214, 140100210);
INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (140100302, 140100307, "かくさん♡どくぎりボム", 0, 140100301, 0, 140100306, 0, 0, 140100301, 2022, 0, 0, 0, 0.59, 0, 0, 0, 0, 140100308, 140100310, 0, 0, 0, 0, 0, 140100305, 140100309, 140100301, 0, "目の前の敵１キャラを中心とした範囲内の敵を毒状態と暗闇状態にする。発動時既に目の前の敵１キャラが毒状態だった場合、毒のダメージが増加し、さらに最も物理防御力が低い敵に物理大ダメージを与える。発動時既に目の前の敵１キャラが毒状態かつ火傷状態だった場合、さらに毒のダメージが増加する。", 0, 0, 0, 0, 140100301, 0, 0, 0, 140100303, 0, 0, 140100301, 1401003, 140100304, 0, 0, 0);
