INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (140200102, 140200107, "サマーナイト・スプラッシュ", 140200113, 140200102, 140200112, 140200106, 0, 0, 0, 1002, 0, 140200102, 0, 0, 0, 0, 0, 0, 140200108, 140200110, 0, 140200112, 0, 0, 0, 140200105, 140200109, 140200102, 0, "目の前の敵１キャラに魔法特大ダメージを２回与え、魔法防御力を小ダウンさせる。対象の【チャームスローブ】が７個以上の場合、さらに受けるクリティカルダメージを小アップさせ、与えたダメージに応じて味方全体のＨＰを最大20％回復させる。対象の【チャームスローブ】が最大の場合、さらに与える物理・魔法ダメージを短時間極大ダウンさせ、【チャームスローブ】を３個消費する。", 0, 0, 0, 0, 0, 0, 0, 0, 140200103, 140200111, 0, 140200101, 1402001, 140200104, 0, 0, 0);
INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (140200202, 140200207, "ネオンバットフィズ", 0, 140200202, 0, 140200206, 0, 0, 0, 2002, 140200202, 0, 0, 0.59, 0, 0, 0, 0, 140200208, 0, 0, 0, 140200202, 0, 0, 140200205, 140200209, 0, 0, "目の前の敵１キャラに【チャームスローブ】（上限12）を１個付与し、魔法大ダメージを２回与え、魔法防御力とＴＰを小ダウンさせる。発動時既に対象の【チャームスローブ】が７個以上だった場合、さらに追加でＴＰを小ダウンさせ、自分のＴＰを中回復する。", 0, 0, 0, 0, 0, 0, 0, 0, 140200203, 0, 0, 140200201, 1402002, 140200204, 0, 0, 0);
INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (140200302, 140200307, "ラヴリーインプレッション", 0, 0, 0, 140200306, 0, 0, 0, 2004, 0, 0, 0, 0.59, 0, 0, 0, 0, 140200308, 0, 0, 0, 0, 0, 0, 140200305, 140200309, 0, 0, "目の前の敵１キャラの魔法攻撃力を大ダウン、ＴＰを小ダウンさせ、【チャームスローブ】（上限12）を１個付与する。発動時既に対象の【チャームスローブ】が７個以上だった場合、さらに追加でＴＰを小ダウンさせ、自分の魔法攻撃力を大アップし、味方全体のＴＰを小回復させる。", 0, 0, 0, 0, 0, 0, 0, 0, 140200303, 0, 0, 140200301, 1402003, 140200304, 0, 0, 0);
