INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (140400102, 140400107, "イクリプス・ショット", 140400113, 140400101, 0, 140400106, 140400117, 140400108, 140400101, 1001, 140400105, 0, 0, 0, 0, 140400119, 0, 140400105, 140400108, 140400110, 140400114, 140400112, 0, 140400118, 140400116, 140400105, 140400109, 140400104, 0, "前方範囲内の敵に物理大ダメージを与え、物理防御力を小ダウンさせ、呪い状態にする。発動時既に対象が呪い状態だった場合、物理ダメージと呪いのダメージが増加し、さらに呪詛状態でない場合、呪詛状態にする。発動時既に前方範囲内の最も物理防御力が低い敵が呪い状態かつ呪詛状態だった場合、その敵の最大ＨＰに応じて最大444万の物理割合ダメージを与え、さらに弱体効果が９種類以上の場合、受ける物理ダメージを小アップさせる。", 0, 0, 0, 140400104, 0, 0, 140400105, 0, 140400103, 140400111, 0, 140400101, 1404001, 140400104, 140400115, 140400114, 0);
