INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (140700102, 140700107, "ナイトフォールストレイフ", 0, 0, 0, 140700106, 0, 140700102, 0, 1001, 0, 0, 0, 0, 0, 0, 0, 0, 140700108, 0, 0, 0, 140700102, 0, 0, 140700105, 140700109, 140700102, 0, "目の前の敵１キャラに物理特大ダメージを２回与え、物理防御力を小ダウンさせる。発動時既に対象の弱体効果が７種類以上だった場合、物理防御力のダウン量が増加し、さらに受けるクリティカルダメージを小アップさせ、自分を中心とした範囲内の味方に物理無効バリアを展開する。", 0, 0, 0, 0, 0, 0, 140700102, 0, 140700103, 0, 0, 140700101, 1407001, 140700104, 0, 0, 0);
INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (140700202, 0, "ラピッドエレガント", 0, 0, 0, 140700206, 0, 0, 0, 2001, 0, 0, 0, 1.05, 0, 0, 0, 140700202, 0, 0, 0, 0, 140700202, 0, 0, 140700205, 0, 140700202, 0, "目の前の敵１キャラに物理大ダメージを２回与え、物理防御力を小ダウン、受けるクリティカルダメージを小アップさせる。発動時既に対象の弱体効果が７種類以上だった場合、物理防御力のダウン量が増加する。", 0, 0, 0, 0, 0, 0, 0, 0, 140700203, 0, 0, 140700201, 1407002, 140700204, 0, 0, 0);
INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (140700302, 140700307, "イルミネートフレア", 0, 0, 0, 140700306, 0, 0, 0, 2003, 0, 0, 0, 1.05, 0, 0, 0, 0, 140700308, 140700310, 0, 140700312, 0, 0, 0, 140700305, 140700309, 0, 0, "目の前の敵１キャラをスタンさせ、暗闇状態にし、物理攻撃力を大ダウンさせる。自分の物理攻撃力を大アップ、物理クリティカルダメージを小アップ、ＴＰを大回復する。発動時既に目の前の敵の弱体効果が７種類以上だった場合、物理攻撃力と物理クリティカルダメージのアップ量が増加し、さらに自分を中心とした範囲内の闇属性の味方のＴＰを小回復させる。", 0, 0, 0, 0, 0, 0, 0, 0, 140700303, 140700311, 0, 140700301, 1407003, 140700304, 0, 0, 0);
INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (140710102, 0, "カウンタースナイプ", 0, 0, 0, 140710106, 0, 0, 0, 2017, 0, 0, 0, 1.05, 0, 0, 0, 0, 0, 0, 0, 0, 140710103, 0, 0, 140710105, 0, 0, 0, "敵から攻撃を受けた時に発動し、その敵に物理中ダメージを与え、回避を大ダウンさせる。このスキルは必ずクリティカルし、発動後一定時間発動しない。", 0, 0, 0, 0, 0, 0, 0, 0, 140710103, 0, 0, 140710101, 1407101, 140710104, 0, 0, 0);
