INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (141000102, 141000107, "君と出逢い、君にキック", 0, 141000102, 0, 141000106, 0, 0, 0, 1001, 141000106, 141000111, 0, 0, 0, 0, 0, 0, 141000108, 141000110, 0, 141000112, 141000102, 0, 0, 141000105, 141000109, 0, 0, "前方の最も遠くの敵に物理特大ダメージを与え、物理防御力を中ダウンさせ、大きく引き寄せる。バトルの残り時間が30秒未満の場合、敵全体が対象になる。バトルの残り時間が10秒未満の場合、自分の【スタミナ】を半分消費し、消費した【スタミナ】の量に応じてダメージ倍率が増加する。", 0, 0, 0, 0, 0, 0, 141000106, 0, 141000103, 141000111, 0, 141000101, 1410001, 141000104, 0, 0, 0);
INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (141000202, 141000207, "不沈艦抜錨・LoAコース", 0, 0, 0, 141000206, 0, 141000208, 0, 2001, 0, 0, 0, 1.05, 0, 0, 0, 141000204, 141000208, 141000210, 0, 141000212, 0, 0, 0, 141000205, 141000209, 141000204, 0, "前方の最も遠くの敵に物理大ダメージを与え、物理防御力を小ダウン、受けるクリティカルダメージを小アップさせる。対象の敵の弱体効果の種類の数に応じて、自分の【スタミナ】（上限564）を最大で42回復する。バトルの残り時間が30秒未満の場合、敵への効果は前方の最も遠くの敵を中心とした範囲内の敵が対象になる。バトルの残り時間が10秒未満の場合、さらに自分のＴＰを特大回復する。", 0, 0, 0, 0, 141000208, 0, 141000207, 0, 141000203, 141000211, 0, 141000201, 1410002, 141000204, 0, 0, 0);
