INSERT INTO `v1_9d431d2ccb6e88ae11f56044904bc9ee624728a40d7f1e3b91cbe4642cedffe8` VALUES (181001202, 181001207, "フレンズリンケージ+", 0, 0, 0, 181001206, 0, 0, 0, 2002, 0, 0, 0, 1.59, 0, 0, 0, 0, 181001208, 181001210, 0, 0, 0, 0, 0, 181001205, 181001209, 0, 0, "目の前の敵１キャラに【友情の魔印】の数に応じてダメージが増加する魔法小ダメージを２回与える。【友情の魔印】が最大の場合、さらに追加で魔法大ダメージを与える。自分の魔法攻撃力と魔法クリティカルを大アップ、魔法クリティカルダメージを小アップ、ＴＰを小回復する。", 0, 0, 0, 0, 0, 0, 0, 0, 181001203, 0, 0, 181001201, 1810012, 181001204, 0, 0, 0);
